package com.naimat.autotimelinesync.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.net.Uri;import android.os.*;import com.naimat.autotimelinesync.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
public final class TestRunner extends Instrumentation {
 JSONArray results=new JSONArray();Context c;File output;MainActivity activity;Project project;String original;boolean syncOnly;
 interface Task{void run()throws Exception;}void test(String name,Task t){JSONObject r=new JSONObject();try{t.run();r.put("status","PASS");}catch(Throwable e){try{r.put("status","FAIL").put("error",e.toString());}catch(Exception ignored){}}try{r.put("test",name);results.put(r);Bundle progress=new Bundle();progress.putString("stream",name+": "+r.optString("status")+" "+r.optString("error")+"\n");sendStatus(0,progress);}catch(Exception ignored){}}
 void ok(boolean value,String message)throws Exception{if(!value)throw new Exception(message);}
 void reject(String content,String path)throws Exception{try{ATSModel.parse(content);throw new Exception("Invalid package was accepted.");}catch(Exception e){if(e.getMessage().equals("Invalid package was accepted."))throw e;ok(e.getMessage().contains(path),"Error lacks path "+path+": "+e.getMessage());}}
 String read(InputStream s)throws Exception{try(InputStream in=s;ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[]buf=new byte[16384];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return b.toString("UTF-8");}}
 void picture(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(output,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 android.view.View find(android.view.View view,String label){if(view instanceof android.widget.Button&&((android.widget.Button)view).getText().toString().equalsIgnoreCase(label))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){android.view.View result=find(g.getChildAt(i),label);if(result!=null)return result;}}return null;}
 void click(String label)throws Exception{final android.view.View[]v=new android.view.View[1];runOnMainSync(()->{v[0]=find(activity.getWindow().getDecorView(),label);if(v[0]!=null)v[0].performClick();});ok(v[0]!=null,"Missing button "+label);waitForIdleSync();}
 android.widget.ScrollView scroll(android.view.View view){if(view instanceof android.widget.ScrollView)return (android.widget.ScrollView)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){android.widget.ScrollView r=scroll(g.getChildAt(i));if(r!=null)return r;}}return null;}
 void extraTests(){
 test("phone caption inspector and Look/Sound tabs",()->{runOnMainSync(()->scroll(activity.getWindow().getDecorView()).fullScroll(android.view.View.FOCUS_DOWN));Thread.sleep(800);picture("03-phone-captions");click("Look");Thread.sleep(600);picture("04-phone-look");click("Sound");Thread.sleep(600);picture("05-phone-sound");});
 test("export dialog opens",()->{click("Export");Thread.sleep(700);picture("06-export-dialog");runOnMainSync(()->{android.view.View v=getUiAutomation()==null?null:activity.getWindow().getDecorView();});getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);Thread.sleep(500);});
 test("heavy caption text has filled white pixels",()->{JSONObject j=new JSONObject(original);j.getJSONObject("caption_style").put("preset","Hormozi Style");Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);comp.render(b,42);int whites=0;for(int y=400;y<550;y++)for(int x=20;x<340;x++){int pixel=b.getPixel(x,y);if(Color.red(pixel)>220&&Color.green(pixel)>220&&Color.blue(pixel)>220)whites++;}ok(whites>500,"Thin outline or black text: white count "+whites);b.recycle();comp.close();});
 test("caption fade has no black outline at frame zero",()->{JSONObject on=new JSONObject(original),off=new JSONObject(original);off.getJSONObject("caption_style").put("enabled",false);Compositor a=new Compositor(c,ATSModel.parse(on.toString()),project.media),b=new Compositor(c,ATSModel.parse(off.toString()),project.media);Bitmap x=Bitmap.createBitmap(180,320,Bitmap.Config.ARGB_8888),y=Bitmap.createBitmap(180,320,Bitmap.Config.ARGB_8888);a.render(x,0);b.render(y,0);ok(x.sameAs(y),"Invisible caption left a shadow/outline");x.recycle();y.recycle();a.close();b.close();});
 test("explicit zero grain overrides inherited look grain",()->{JSONObject j=new JSONObject(original);j.remove("moments");j.getJSONObject("caption_style").put("enabled",false);j.getJSONObject("style").put("look","DARK_NOIR");j.getJSONObject("direction").getJSONObject("finish").put("grain",0);j.getJSONArray("scenes").getJSONObject(1).put("motion","STATIC");Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap a=Bitmap.createBitmap(180,320,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(180,320,Bitmap.Config.ARGB_8888);comp.render(a,90);comp.render(b,91);ok(a.sameAs(b),"Grain remained active at zero");a.recycle();b.recycle();comp.close();});
 test("foreground export cancel cleans job and stops service",()->{Project p=new Project(new MediaFiles(c));p.load(project.save().toString());ExportService.project=p;ExportService.destination=Uri.fromFile(new File(output,"cancelled.mp4"));ExportService.width=360;ExportService.height=640;ExportService.quality=false;runOnMainSync(()->c.startForegroundService(new Intent(c,ExportService.class)));long deadline=System.currentTimeMillis()+90000;while((!ExportService.running||ExportService.percent<15)&&System.currentTimeMillis()<deadline)Thread.sleep(100);ok(ExportService.running,"Export service did not run: "+ExportService.error);picture("07-export-progress");ExportService.cancel.set(true);while(ExportService.running&&System.currentTimeMillis()<deadline)Thread.sleep(100);ok(!ExportService.running,"Cancel did not finish");ok(ExportService.phase.equals("Export cancelled"),"Unexpected service state "+ExportService.phase+" "+ExportService.error);File jobs=new File(c.getCacheDir(),"export-jobs");ok(jobs.listFiles()==null||jobs.listFiles().length==0,"Export cache remained");});
 test("K-weighted loudness measures a known stereo sine",()->{Loudness l=new Loudness();for(int i=0;i<48000*3;i++){double v=.1*Math.sin(i*2*Math.PI*1000/48000);l.add(v,v);}ok(l.integrated()>-21&&l.integrated()<-19,"Unexpected integrated loudness "+l.integrated());});
 test("all 15 declared SFX produce audio and global Off is silent",()->{Project p=new Project(new MediaFiles(c));p.load(project.save().toString());JSONObject j=new JSONObject(original);j.remove("moments");j.getJSONObject("direction").put("voice_level",0).put("music_level",0);JSONArray scenes=new JSONArray();List<String>types=new ArrayList<>(new TreeSet<>(ATSModel.SFX));for(int i=0;i<16;i++){JSONObject s=new JSONObject().put("id",String.format(java.util.Locale.ROOT,"%03d",i+1)).put("image_id",String.format(java.util.Locale.ROOT,"%03d",i+1)).put("start",i*.5).put("end",(i+1)*.5).put("voice_text","").put("motion","STATIC").put("transition","HARD_CUT");if(i>0)s.put("sfx",new JSONArray().put(new JSONObject().put("id",types.get(i-1)).put("variant",2).put("gain_db",-12).put("pitch_cents",100)));scenes.put(s);}j.put("scenes",scenes);p.script=j.toString();p.overrides=new JSONObject();p.music=null;p.resolve();File job=new File(output,"sfx-test");job.mkdirs();File wav=AudioEngine.mix(c,p,job,new AtomicBoolean(),(s,x)->{});try(RandomAccessFile file=new RandomAccessFile(wav,"r")){for(int i=1;i<16;i++){file.seek(44+i*24000L*4);int energy=0;for(int n=0;n<4800*2;n++)energy+=Math.abs((short)(file.readUnsignedByte()|(file.readUnsignedByte()<<8)));ok(energy>10000,"SFX silent "+types.get(i-1));}}MediaFiles.clean(job,output);p.set("direction","sfx_enabled",false);job.mkdirs();wav=AudioEngine.mix(c,p,job,new AtomicBoolean(),(s,x)->{});try(RandomAccessFile file=new RandomAccessFile(wav,"r")){file.seek(44);for(int i=0;i<8*48000*2;i++)ok(file.readUnsignedByte()==0&&file.readUnsignedByte()==0,"Off still applied SFX");}MediaFiles.clean(job,output);});
 test("LOUDNORM output reaches requested integrated loudness",()->{Project p=new Project(new MediaFiles(c));p.load(project.save().toString());p.music=null;p.set("audio","master",new JSONObject().put("mode","LOUDNORM").put("target_lufs",-16).put("true_peak_db",-1));File job=new File(output,"loudness-test");job.mkdirs();File wav=AudioEngine.mix(c,p,job,new AtomicBoolean(),(s,x)->{});Loudness l=new Loudness();try(RandomAccessFile f=new RandomAccessFile(wav,"r")){f.seek(44);for(int i=0;i<8*48000;i++){double a=(short)(f.readUnsignedByte()|(f.readUnsignedByte()<<8))/32768.0,b=(short)(f.readUnsignedByte()|(f.readUnsignedByte()<<8))/32768.0;l.add(a,b);}}ok(Math.abs(l.integrated()+16)<.3,"Normalization drift "+l.integrated());MediaFiles.clean(job,output);});
 test("foreground service saves final MP4 and clears cache",()->{Project p=new Project(new MediaFiles(c));p.load(project.save().toString());File saved=new File(output,"service-export.mp4");ExportService.project=p;ExportService.destination=Uri.fromFile(saved);ExportService.width=360;ExportService.height=640;ExportService.quality=false;runOnMainSync(()->c.startForegroundService(new Intent(c,ExportService.class)));long limit=System.currentTimeMillis()+180000;while(!ExportService.running&&System.currentTimeMillis()<limit)Thread.sleep(50);while(ExportService.running&&System.currentTimeMillis()<limit)Thread.sleep(100);ok(ExportService.percent==100&&ExportService.result!=null&&saved.length()>1000,"Foreground export failed "+ExportService.phase+" "+ExportService.error);File jobs=new File(c.getCacheDir(),"export-jobs");ok(jobs.listFiles()==null||jobs.listFiles().length==0,"Completed export left cache");Thread.sleep(600);waitForIdleSync();picture("08-export-complete");});
 }
 @Override public void onCreate(Bundle arguments){syncOnly=arguments!=null&&arguments.getString("sync_only","false").equals("true");super.onCreate(arguments);start();}
 @Override public void onStart(){c=getTargetContext();output=c.getExternalFilesDir("verification");output.mkdirs();try{new File(c.getFilesDir(),"autosave.ats3").delete();activity=(MainActivity)startActivitySync(new Intent().setClassName(c,"com.naimat.autotimelinesync.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Thread.sleep(1000);test("launch screenshot",()->picture("01-launch"));runOnMainSync(()->activity.demo());waitForIdleSync();Thread.sleep(1800);project=activity.project;original=project.script;if(syncOnly){SyncTests.run(this);finishReport();return;}
 test("V2 import and media validation",()->{project.resolve();project.media.validate(project.model,project.narration);ok(project.model.totalFrames==240,"Wrong frame count");ok(project.media.images.size()==4,"Wrong image mapping");});
 test("loaded editor screenshot",()->picture("02-editor"));
 test("four aspect ratios",()->{String[]os={"VERTICAL","HORIZONTAL","SQUARE","PORTRAIT"},as={"9:16","16:9","1:1","4:5"};for(int i=0;i<4;i++){JSONObject j=new JSONObject(original);j.put("format",new JSONObject().put("orientation",os[i]).put("aspect_ratio",as[i]));ATSModel m=ATSModel.parse(j.toString());ok(m.aspect.equals(as[i]),"Wrong ratio");}});
 test("duplicate JSON keys rejected",()->reject(original.replace("\"fps\":30","\"fps\":30,\"fps\":24"),"$") );
 test("trailing JSON rejected",()->reject(original+"{}","$"));
 test("obsolete V1 rejected",()->reject(original.replace("ATS_PACKAGE_V2","ATS_PACKAGE_V1"),"$.schema"));
 test("unknown field rejected",()->{JSONObject j=new JSONObject(original);j.put("layers",new JSONArray());reject(j.toString(),"$.layers");});
 test("wrong enum case rejected",()->{JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("motion","pan_right");reject(j.toString(),"$.scenes[1].motion");});
 test("scene gap rejected",()->{JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("start",2.1);reject(j.toString(),"$.scenes[1].start");});
 test("missing word index rejected",()->{JSONObject j=new JSONObject(original);j.getJSONArray("captions").getJSONObject(0).put("word_end_index",999);reject(j.toString(),"$.captions[0]");});
 test("format mismatch rejected",()->{JSONObject j=new JSONObject(original);j.getJSONObject("format").put("aspect_ratio","16:9");reject(j.toString(),"$.format.aspect_ratio");});
 test("bad circle is skipped with notice",()->{JSONObject j=new JSONObject(original);j.getJSONArray("moments").getJSONObject(1).put("box",new JSONArray("[0,0,0.8,0.8]"));ATSModel m=ATSModel.parse(j.toString());ok(m.moments.size()==1&&!m.notices.isEmpty(),"Invalid circle silent");});
 test("frame math HALF_UP",()->ok(ATSModel.frame(.05,30)==2&&ATSModel.frame(1.05,30)==32,"Rounding failed"));
 test("project serialization and reopen",()->{Project p=new Project(new MediaFiles(c));p.load(project.save().toString());p.media.validate(p.model,p.narration);ok(p.model.scenes.size()==4&&p.music!=null,"Project lost fields");});
 test("all 10 motions render",()->{for(String motion:ATSModel.MOTIONS){JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("motion",motion);Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);comp.render(b,90);ok(b.getPixel(180,320)!=Color.TRANSPARENT,"Empty motion");b.recycle();comp.close();}});
 test("all 27 transition enums render",()->{for(String type:ATSModel.TRANSITIONS){JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("transition",type).put("transition_config",new JSONObject().put("frames",12));Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);comp.render(b,65);ok(b.getPixel(180,320)!=Color.TRANSPARENT,"Empty transition");if(type.equals("PAPER_TEAR"))try(FileOutputStream s=new FileOutputStream(new File(output,"transition.png"))){b.compress(Bitmap.CompressFormat.PNG,100,s);}b.recycle();comp.close();}});
 test("all caption presets render",()->{for(String preset:ATSModel.PRESETS){JSONObject j=new JSONObject(original);j.getJSONObject("caption_style").put("preset",preset);Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);comp.render(b,42);try(FileOutputStream s=new FileOutputStream(new File(output,"caption-"+preset.replaceAll("[^A-Za-z]","")+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,s);}b.recycle();comp.close();}});
 test("all fonts and 13 looks render",()->{for(String f:ATSModel.FONTS){Compositor comp=new Compositor(c,project.model,project.media);ok(comp.font(f)!=null,"Missing font "+f);comp.close();}for(String look:ATSModel.LOOKS){JSONObject j=new JSONObject(original);j.getJSONObject("style").put("look",look);Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(180,320,Bitmap.Config.ARGB_8888);comp.render(b,42);b.recycle();comp.close();}});
 test("date and circle draw",()->{Compositor comp=new Compositor(c,project.model,project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);for(int frame:new int[]{18,91}){comp.render(b,frame);try(FileOutputStream out=new FileOutputStream(new File(output,"moment-"+frame+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}b.recycle();comp.close();});
 test("7 overlays draw including source photo note",()->{JSONObject j=new JSONObject(original);JSONArray overlays=new JSONArray();String[]types={"DATE_STAMP","HIGHLIGHT_BOX","HOOK_CARD","LOWER_THIRD","MAP_ROUTE","PHOTO_NOTE","TEXT"};for(int i=0;i<types.length;i++){JSONObject o=new JSONObject().put("id","o"+i).put("type",types[i]).put("start",4).put("end",5.8).put("text","Tomorrow").put("scene_id","003");if(types[i].equals("MAP_ROUTE"))o.put("points",new JSONArray("[[0.2,0.4],[0.5,0.6],[0.8,0.4]]"));if(types[i].equals("PHOTO_NOTE"))o.put("points",new JSONArray("[[0.2,0.59],[0.8,0.59],[0.8,0.7],[0.2,0.7]]"));overlays.put(o);}j.put("overlays",overlays);Compositor comp=new Compositor(c,ATSModel.parse(j.toString()),project.media);Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);comp.render(b,153);b.recycle();comp.close();});
 test("audio mix duration, music loops and limiter",()->{File job=new File(output,"audio-test");job.mkdirs();File wav=AudioEngine.mix(c,project,job,new AtomicBoolean(),(s,x)->{});ok(wav.length()==44+8*48000*4,"Audio frame count wrong");try(RandomAccessFile f=new RandomAccessFile(wav,"r")){f.seek(44);int peak=0;for(int i=0;i<8*48000*2;i++){int value=(short)(f.readUnsignedByte()|(f.readUnsignedByte()<<8));peak=Math.max(peak,Math.abs(value));}ok(peak<=29206,"Limiter ceiling exceeded");}MediaFiles.clean(job,output);});
 test("cancel leaves no encoded output",()->{File job=new File(output,"cancel-test");job.mkdirs();AtomicBoolean stop=new AtomicBoolean(true);boolean cancelled=false;try{VideoEngine.export(c,project,job,360,640,false,stop,(s,x)->{});}catch(InterruptedException e){cancelled=true;}finally{MediaFiles.clean(job,output);}ok(cancelled&&!job.exists(),"Cancel or cleanup failed");});
 test("codec capabilities",()->{JSONArray codecs=new JSONArray();for(MediaCodecInfo info:new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos()){if(!info.isEncoder())continue;for(String mime:info.getSupportedTypes()){JSONObject item=new JSONObject().put("name",info.getName()).put("mime",mime);if(mime.startsWith("video/")){MediaCodecInfo.VideoCapabilities v=info.getCapabilitiesForType(mime).getVideoCapabilities();item.put("widths",v.getSupportedWidths().toString()).put("heights",v.getSupportedHeights().toString()).put("rates",v.getSupportedFrameRates().toString()).put("hd",v.areSizeAndRateSupported(720,1280,30)).put("small",v.areSizeAndRateSupported(360,640,30));}codecs.put(item);}}try(FileOutputStream out=new FileOutputStream(new File(output,"codecs.json"))){out.write(codecs.toString(2).getBytes("UTF-8"));}});test("native H264 AAC MP4 export 720×1280",()->{File job=new File(output,"export-test");job.mkdirs();File mp4=VideoEngine.export(c,project,job,720,1280,false,new AtomicBoolean(),(s,x)->{if(x%10==0){Bundle b=new Bundle();b.putString("stream",s+" "+x+"%\n");sendStatus(0,b);}});File finalFile=new File(output,"verified-export.mp4");try(InputStream in=new FileInputStream(mp4);OutputStream out=new FileOutputStream(finalFile)){byte[]buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}MediaMetadataRetriever mm=new MediaMetadataRetriever();try{mm.setDataSource(finalFile.getPath());int rotation=Integer.parseInt(mm.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION));String mw=mm.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH),mh=mm.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT);ok((rotation==90?mh:mw).equals("720"),"Wrong display width");ok((rotation==90?mw:mh).equals("1280"),"Wrong display height");ok(Math.abs(Long.parseLong(mm.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))-8000)<80,"Duration drift");Bitmap frame=mm.getFrameAtTime(1500000,MediaMetadataRetriever.OPTION_CLOSEST);ok(frame!=null,"Output not decodable");try(FileOutputStream out=new FileOutputStream(new File(output,"encoded-frame.png"))){frame.compress(Bitmap.CompressFormat.PNG,100,out);}frame.recycle();}finally{mm.release();}MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(finalFile.getPath());ok(extractor.getTrackCount()==2,"Missing audio/video track");}finally{extractor.release();}MediaFiles.clean(job,output);});
 extraTests();SyncTests.run(this);}catch(Throwable e){test("test runner setup",()->{throw new Exception(e);});}finishReport();}
 private void finishReport(){try{JSONObject report=new JSONObject().put("device",Build.MODEL).put("api",Build.VERSION.SDK_INT).put("tests",results);int fails=0;for(int i=0;i<results.length();i++)if(!results.getJSONObject(i).getString("status").equals("PASS"))fails++;report.put("failures",fails).put("count",results.length());try(FileOutputStream out=new FileOutputStream(new File(output,"results.json"))){out.write(report.toString(2).getBytes("UTF-8"));}Bundle result=new Bundle();result.putString("stream",report.toString(2));finish(fails==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}catch(Exception e){Bundle b=new Bundle();b.putString("stream",e.toString());finish(Activity.RESULT_CANCELED,b);}}
}
